# For each client with a workspace-visible primary contact: one review item
# per employee assigned to that client, assigned to the primary contact,
# scoped into the client's portal, with the shared monthly form attached.
users = api.users.list()
users_by_email = {}
users_by_id = {}
for u in users:
    users_by_id[u['id']] = u
    email = (u.get('email') or '').lower()
    if email:
        users_by_email[email] = u

portals_by_client = {}
for p in api.portals.list():
    if p.get('clientId'):
        portals_by_client[p['clientId']] = p

created_items = []
skipped = []

for client in api.clients.list():
    contact_id = client.get('primaryContactId')
    if not contact_id:
        skipped.append(client['name'] + ': no primary contact')
        continue
    contact = api.contacts.get(contact_id=contact_id)
    contact_email = ((contact or {}).get('email') or '').lower()
    contact_user = users_by_email.get(contact_email)
    if not contact_user:
        skipped.append(client['name'] + ': primary contact has no workspace account')
        continue
    contact_label = contact_user.get('name') or contact_user['email']
    portal = portals_by_client.get(client['id'])

    for emp in api.employees.list(client_id=client['id']):
        emp_user = users_by_id.get(emp['user_id'])
        emp_label = (emp_user or {}).get('name') or (emp_user or {}).get('email') or emp['user_id']
        kwargs = {
            'template_id': params['playbook_template_id'],
            'variables': {
                'employee': {'type': 'entity', 'value': {'id': emp['user_id'], 'label': emp_label}},
                'client_contact': {'type': 'role', 'value': {'kind': 'user', 'id': contact_user['id'], 'label': contact_label}},
                'review_month': {'type': 'text', 'value': params['month_label']},
            },
        }
        if portal:
            kwargs['portal_id'] = portal['portalId']
        result = api.templates.materialize(**kwargs)
        for item_id in result['itemIds']:
            api.workq.attach_form(todo_id=item_id, form_id=params['form_id'])
            created_items.append(item_id)

created_count = len(created_items)
skipped_count = len(skipped)
summary = (
    params['month_label'] + ': created ' + str(created_count)
    + ' review items on one shared form; skipped ' + str(skipped_count)
    + ' clients (' + '; '.join(skipped[:5]) + ('…' if len(skipped) > 5 else '') + ')'
)
